35|static uint8_t downcase(uint8_t c) {
36|  return 'A' <= c && c <= 'Z' ? (uint8_t)(c - 'A' + 'a') : c;
37|}
38|
39|static int memieq(const void *a, const void *b, size_t n) {
40|  size_t i;
41|  const uint8_t *aa = a, *bb = b;
42|
43|  for (i = 0; i < n; ++i) {
44|    if (downcase(aa[i]) != downcase(bb[i])) {
45|      return 0;
46|    }
47|  }
48|  return 1;
49|}
50|
51|#define lstrieq(A, B, N) ((sizeof((A)) - 1) == (N) && memieq((A), (B), (N)))
52|
53|static int64_t parse_uint(const uint8_t *s, size_t len) {
54|  int64_t n = 0;
55|  size_t i;
56|  if (len == 0) {
57|    return -1;
58|  }
59|  for (i = 0; i < len; ++i) {
60|    if ('0' <= s[i] && s[i] <= '9') {
61|      if (n > INT64_MAX / 10) {
62|        return -1;
63|      }
64|      n *= 10;
65|      if (n > INT64_MAX - (s[i] - '0')) {
66|        return -1;
67|      }
68|      n += s[i] - '0';
69|      continue;
70|    }
71|    return -1;
72|  }
73|  return n;
74|}
75|
76|static int lws(const uint8_t *s, size_t n) {
77|  size_t i;
78|  for (i = 0; i < n; ++i) {
79|    if (s[i] != ' ' && s[i] != '\t') {
80|      return 0;
81|    }
82|  }
83|  return 1;
84|}
