86|static int check_pseudo_header(nghttp2_stream *stream, const nghttp2_hd_nv *nv,
87|                               int flag) {
88|  if (stream->http_flags & flag) {
89|    return 0;
90|  }
91|  if (lws(nv->value->base, nv->value->len)) {
92|    return 0;
93|  }
94|  stream->http_flags = (uint16_t)(stream->http_flags | flag);
95|  return 1;
96|}
