98|static int expect_response_body(nghttp2_stream *stream) {
99|  return (stream->http_flags & NGHTTP2_HTTP_FLAG_METH_HEAD) == 0 &&
100|         stream->status_code / 100 != 1 && stream->status_code != 304 &&
101|         stream->status_code != 204;
102|}
