116|static int http_request_on_header(nghttp2_stream *stream, nghttp2_hd_nv *nv,
117|                                  int trailer, int connect_protocol) {
118|  nghttp2_extpri extpri;
119|
120|  if (nv->name->base[0] == ':') {
121|    if (trailer ||
122|        (stream->http_flags & NGHTTP2_HTTP_FLAG_PSEUDO_HEADER_DISALLOWED)) {
123|      return NGHTTP2_ERR_HTTP_HEADER;
124|    }
125|  }
126|
127|  switch (nv->token) {
128|  case NGHTTP2_TOKEN__AUTHORITY:
129|    if (!check_pseudo_header(stream, nv, NGHTTP2_HTTP_FLAG__AUTHORITY)) {
130|      return NGHTTP2_ERR_HTTP_HEADER;
131|    }
132|    break;
133|  case NGHTTP2_TOKEN__METHOD:
134|    if (!check_pseudo_header(stream, nv, NGHTTP2_HTTP_FLAG__METHOD)) {
135|      return NGHTTP2_ERR_HTTP_HEADER;
136|    }
137|    switch (nv->value->len) {
138|    case 4:
139|      if (lstreq("HEAD", nv->value->base, nv->value->len)) {
140|        stream->http_flags |= NGHTTP2_HTTP_FLAG_METH_HEAD;
141|      }
142|      break;
143|    case 7:
144|      switch (nv->value->base[6]) {
145|      case 'T':
146|        if (lstreq("CONNECT", nv->value->base, nv->value->len)) {
147|          if (stream->stream_id % 2 == 0) {
148|            /* we won't allow CONNECT for push */
149|            return NGHTTP2_ERR_HTTP_HEADER;
150|          }
151|          stream->http_flags |= NGHTTP2_HTTP_FLAG_METH_CONNECT;
152|        }
153|        break;
154|      case 'S':
155|        if (lstreq("OPTIONS", nv->value->base, nv->value->len)) {
156|          stream->http_flags |= NGHTTP2_HTTP_FLAG_METH_OPTIONS;
157|        }
158|        break;
159|      }
160|      break;
161|    }
162|    break;
163|  case NGHTTP2_TOKEN__PATH:
164|    if (!check_pseudo_header(stream, nv, NGHTTP2_HTTP_FLAG__PATH)) {
165|      return NGHTTP2_ERR_HTTP_HEADER;
166|    }
167|    if (nv->value->base[0] == '/') {
168|      stream->http_flags |= NGHTTP2_HTTP_FLAG_PATH_REGULAR;
169|    } else if (nv->value->len == 1 && nv->value->base[0] == '*') {
170|      stream->http_flags |= NGHTTP2_HTTP_FLAG_PATH_ASTERISK;
171|    }
172|    break;
173|  case NGHTTP2_TOKEN__SCHEME:
174|    if (!check_pseudo_header(stream, nv, NGHTTP2_HTTP_FLAG__SCHEME)) {
175|      return NGHTTP2_ERR_HTTP_HEADER;
176|    }
177|    if ((nv->value->len == 4 && memieq("http", nv->value->base, 4)) ||
178|        (nv->value->len == 5 && memieq("https", nv->value->base, 5))) {
179|      stream->http_flags |= NGHTTP2_HTTP_FLAG_SCHEME_HTTP;
180|    }
181|    break;
182|  case NGHTTP2_TOKEN__PROTOCOL:
183|    if (!connect_protocol) {
184|      return NGHTTP2_ERR_HTTP_HEADER;
185|    }
186|
187|    if (!check_pseudo_header(stream, nv, NGHTTP2_HTTP_FLAG__PROTOCOL)) {
188|      return NGHTTP2_ERR_HTTP_HEADER;
189|    }
190|    break;
191|  case NGHTTP2_TOKEN_HOST:
192|    if (!check_pseudo_header(stream, nv, NGHTTP2_HTTP_FLAG_HOST)) {
193|      return NGHTTP2_ERR_HTTP_HEADER;
194|    }
195|    break;
196|  case NGHTTP2_TOKEN_CONTENT_LENGTH: {
197|    if (stream->content_length != -1) {
198|      return NGHTTP2_ERR_HTTP_HEADER;
199|    }
200|    stream->content_length = parse_uint(nv->value->base, nv->value->len);
201|    if (stream->content_length == -1) {
202|      return NGHTTP2_ERR_HTTP_HEADER;
203|    }
204|    break;
205|  }
206|  /* disallowed header fields */
207|  case NGHTTP2_TOKEN_CONNECTION:
208|  case NGHTTP2_TOKEN_KEEP_ALIVE:
209|  case NGHTTP2_TOKEN_PROXY_CONNECTION:
210|  case NGHTTP2_TOKEN_TRANSFER_ENCODING:
211|  case NGHTTP2_TOKEN_UPGRADE:
212|    return NGHTTP2_ERR_HTTP_HEADER;
213|  case NGHTTP2_TOKEN_TE:
214|    if (!lstrieq("trailers", nv->value->base, nv->value->len)) {
215|      return NGHTTP2_ERR_HTTP_HEADER;
216|    }
217|    break;
218|  case NGHTTP2_TOKEN_PRIORITY:
219|    if (!trailer &&
220|        (stream->flags & NGHTTP2_STREAM_FLAG_NO_RFC7540_PRIORITIES)) {
221|      nghttp2_extpri_from_uint8(&extpri, stream->http_extpri);
222|      if (nghttp2_http_parse_priority(&extpri, nv->value->base,
223|                                      nv->value->len) == 0) {
224|        stream->http_extpri = nghttp2_extpri_to_uint8(&extpri);
225|      }
226|    }
227|    break;
228|  default:
229|    if (nv->name->base[0] == ':') {
230|      return NGHTTP2_ERR_HTTP_HEADER;
231|    }
232|  }
233|
234|  if (nv->name->base[0] != ':') {
235|    stream->http_flags |= NGHTTP2_HTTP_FLAG_PSEUDO_HEADER_DISALLOWED;
236|  }
237|
238|  return 0;
239|}
240|
241|static int http_response_on_header(nghttp2_stream *stream, nghttp2_hd_nv *nv,
242|                                   int trailer) {
243|  if (nv->name->base[0] == ':') {
244|    if (trailer ||
245|        (stream->http_flags & NGHTTP2_HTTP_FLAG_PSEUDO_HEADER_DISALLOWED)) {
246|      return NGHTTP2_ERR_HTTP_HEADER;
247|    }
248|  }
249|
250|  switch (nv->token) {
251|  case NGHTTP2_TOKEN__STATUS: {
252|    if (!check_pseudo_header(stream, nv, NGHTTP2_HTTP_FLAG__STATUS)) {
253|      return NGHTTP2_ERR_HTTP_HEADER;
254|    }
255|    if (nv->value->len != 3) {
256|      return NGHTTP2_ERR_HTTP_HEADER;
257|    }
258|    stream->status_code = (int16_t)parse_uint(nv->value->base, nv->value->len);
259|    if (stream->status_code == -1 || stream->status_code == 101) {
260|      return NGHTTP2_ERR_HTTP_HEADER;
261|    }
262|    break;
263|  }
264|  case NGHTTP2_TOKEN_CONTENT_LENGTH: {
265|    if (stream->status_code == 204) {
266|      /* content-length header field in 204 response is prohibited by
267|         RFC 7230.  But some widely used servers send content-length:
268|         0.  Until they get fixed, we ignore it. */
269|      if (stream->content_length != -1) {
270|        /* Found multiple content-length field */
271|        return NGHTTP2_ERR_HTTP_HEADER;
272|      }
273|      if (!lstrieq("0", nv->value->base, nv->value->len)) {
274|        return NGHTTP2_ERR_HTTP_HEADER;
275|      }
276|      stream->content_length = 0;
277|      return NGHTTP2_ERR_REMOVE_HTTP_HEADER;
278|    }
279|    if (stream->status_code / 100 == 1) {
280|      return NGHTTP2_ERR_HTTP_HEADER;
281|    }
282|    /* https://tools.ietf.org/html/rfc7230#section-3.3.3 */
283|    if (stream->status_code / 100 == 2 &&
284|        (stream->http_flags & NGHTTP2_HTTP_FLAG_METH_CONNECT)) {
285|      return NGHTTP2_ERR_REMOVE_HTTP_HEADER;
286|    }
287|    if (stream->content_length != -1) {
288|      return NGHTTP2_ERR_HTTP_HEADER;
289|    }
290|    stream->content_length = parse_uint(nv->value->base, nv->value->len);
291|    if (stream->content_length == -1) {
292|      return NGHTTP2_ERR_HTTP_HEADER;
293|    }
294|    break;
295|  }
296|  /* disallowed header fields */
297|  case NGHTTP2_TOKEN_CONNECTION:
298|  case NGHTTP2_TOKEN_KEEP_ALIVE:
299|  case NGHTTP2_TOKEN_PROXY_CONNECTION:
300|  case NGHTTP2_TOKEN_TRANSFER_ENCODING:
301|  case NGHTTP2_TOKEN_UPGRADE:
302|    return NGHTTP2_ERR_HTTP_HEADER;
303|  case NGHTTP2_TOKEN_TE:
304|    if (!lstrieq("trailers", nv->value->base, nv->value->len)) {
305|      return NGHTTP2_ERR_HTTP_HEADER;
306|    }
307|    break;
308|  default:
309|    if (nv->name->base[0] == ':') {
310|      return NGHTTP2_ERR_HTTP_HEADER;
311|    }
312|  }
313|
314|  if (nv->name->base[0] != ':') {
315|    stream->http_flags |= NGHTTP2_HTTP_FLAG_PSEUDO_HEADER_DISALLOWED;
316|  }
317|
318|  return 0;
319|}
