321|static int check_scheme(const uint8_t *value, size_t len) {
322|  const uint8_t *last;
323|  if (len == 0) {
324|    return 0;
325|  }
326|
327|  if (!(('A' <= *value && *value <= 'Z') || ('a' <= *value && *value <= 'z'))) {
328|    return 0;
329|  }
330|
331|  last = value + len;
332|  ++value;
333|
334|  for (; value != last; ++value) {
335|    if (!(('A' <= *value && *value <= 'Z') ||
336|          ('a' <= *value && *value <= 'z') ||
337|          ('0' <= *value && *value <= '9') || *value == '+' || *value == '-' ||
338|          *value == '.')) {
339|      return 0;
340|    }
341|  }
342|  return 1;
343|}
