345|int nghttp2_http_on_header(nghttp2_session *session, nghttp2_stream *stream,
346|                           nghttp2_frame *frame, nghttp2_hd_nv *nv,
347|                           int trailer) {
348|  int rv;
349|
350|  /* We are strict for pseudo header field.  One bad character should
351|     lead to fail.  OTOH, we should be a bit forgiving for regular
352|     headers, since existing public internet has so much illegal
353|     headers floating around and if we kill the stream because of
354|     this, we may disrupt many web sites and/or libraries.  So we
355|     become conservative here, and just ignore those illegal regular
356|     headers. */
357|  if (!nghttp2_check_header_name(nv->name->base, nv->name->len)) {
358|    size_t i;
359|    if (nv->name->len > 0 && nv->name->base[0] == ':') {
360|      return NGHTTP2_ERR_HTTP_HEADER;
361|    }
362|    /* header field name must be lower-cased without exception */
363|    for (i = 0; i < nv->name->len; ++i) {
364|      uint8_t c = nv->name->base[i];
365|      if ('A' <= c && c <= 'Z') {
366|        return NGHTTP2_ERR_HTTP_HEADER;
367|      }
368|    }
369|    /* When ignoring regular headers, we set this flag so that we
370|       still enforce header field ordering rule for pseudo header
371|       fields. */
372|    stream->http_flags |= NGHTTP2_HTTP_FLAG_PSEUDO_HEADER_DISALLOWED;
373|    return NGHTTP2_ERR_IGN_HTTP_HEADER;
374|  }
375|
376|  switch (nv->token) {
377|  case NGHTTP2_TOKEN__METHOD:
378|    rv = nghttp2_check_method(nv->value->base, nv->value->len);
379|    break;
380|  case NGHTTP2_TOKEN__PATH:
381|    rv = nghttp2_check_path(nv->value->base, nv->value->len);
382|    break;
383|  case NGHTTP2_TOKEN__AUTHORITY:
384|  case NGHTTP2_TOKEN_HOST:
385|    if (session->server || frame->hd.type == NGHTTP2_PUSH_PROMISE) {
386|      rv = nghttp2_check_authority(nv->value->base, nv->value->len);
387|    } else {
388|      rv = nghttp2_check_header_value(nv->value->base, nv->value->len);
389|    }
390|    break;
391|  case NGHTTP2_TOKEN__SCHEME:
392|    rv = check_scheme(nv->value->base, nv->value->len);
393|    break;
394|  default:
395|    rv = nghttp2_check_header_value(nv->value->base, nv->value->len);
396|  }
397|
398|  if (rv == 0) {
399|    assert(nv->name->len > 0);
400|    if (nv->name->base[0] == ':') {
401|      return NGHTTP2_ERR_HTTP_HEADER;
402|    }
403|    /* When ignoring regular headers, we set this flag so that we
404|       still enforce header field ordering rule for pseudo header
405|       fields. */
406|    stream->http_flags |= NGHTTP2_HTTP_FLAG_PSEUDO_HEADER_DISALLOWED;
407|    return NGHTTP2_ERR_IGN_HTTP_HEADER;
408|  }
409|
410|  if (session->server || frame->hd.type == NGHTTP2_PUSH_PROMISE) {
411|    return http_request_on_header(stream, nv, trailer,
412|                                  session->server &&
413|                                      session->pending_enable_connect_protocol);
414|  }
415|
416|  return http_response_on_header(stream, nv, trailer);
417|}
