419|int nghttp2_http_on_request_headers(nghttp2_stream *stream,
420|                                    nghttp2_frame *frame) {
421|  if (!(stream->http_flags & NGHTTP2_HTTP_FLAG__PROTOCOL) &&
422|      (stream->http_flags & NGHTTP2_HTTP_FLAG_METH_CONNECT)) {
423|    if ((stream->http_flags &
424|         (NGHTTP2_HTTP_FLAG__SCHEME | NGHTTP2_HTTP_FLAG__PATH)) ||
425|        (stream->http_flags & NGHTTP2_HTTP_FLAG__AUTHORITY) == 0) {
426|      return -1;
427|    }
428|    stream->content_length = -1;
429|  } else {
430|    if ((stream->http_flags & NGHTTP2_HTTP_FLAG_REQ_HEADERS) !=
431|            NGHTTP2_HTTP_FLAG_REQ_HEADERS ||
432|        (stream->http_flags &
433|         (NGHTTP2_HTTP_FLAG__AUTHORITY | NGHTTP2_HTTP_FLAG_HOST)) == 0) {
434|      return -1;
435|    }
436|    if ((stream->http_flags & NGHTTP2_HTTP_FLAG__PROTOCOL) &&
437|        ((stream->http_flags & NGHTTP2_HTTP_FLAG_METH_CONNECT) == 0 ||
438|         (stream->http_flags & NGHTTP2_HTTP_FLAG__AUTHORITY) == 0)) {
439|      return -1;
440|    }
441|    if (!check_path(stream)) {
442|      return -1;
443|    }
444|  }
445|
446|  if (frame->hd.type == NGHTTP2_PUSH_PROMISE) {
447|    /* we are going to reuse data fields for upcoming response.  Clear
448|       them now, except for method flags. */
449|    stream->http_flags &= NGHTTP2_HTTP_FLAG_METH_ALL;
450|    stream->content_length = -1;
451|  }
452|
453|  return 0;
454|}
455|
456|int nghttp2_http_on_response_headers(nghttp2_stream *stream) {
457|  if ((stream->http_flags & NGHTTP2_HTTP_FLAG__STATUS) == 0) {
458|    return -1;
459|  }
460|
461|  if (stream->status_code / 100 == 1) {
462|    /* non-final response */
463|    stream->http_flags =
464|        (uint16_t)((stream->http_flags & NGHTTP2_HTTP_FLAG_METH_ALL) |
465|                   NGHTTP2_HTTP_FLAG_EXPECT_FINAL_RESPONSE);
466|    stream->content_length = -1;
467|    stream->status_code = -1;
468|    return 0;
469|  }
470|
471|  stream->http_flags =
472|      (uint16_t)(stream->http_flags & ~NGHTTP2_HTTP_FLAG_EXPECT_FINAL_RESPONSE);
473|
474|  if (!expect_response_body(stream)) {
475|    stream->content_length = 0;
476|  } else if (stream->http_flags & (NGHTTP2_HTTP_FLAG_METH_CONNECT |
477|                                   NGHTTP2_HTTP_FLAG_METH_UPGRADE_WORKAROUND)) {
478|    stream->content_length = -1;
479|  }
480|
481|  return 0;
482|}
