484|int nghttp2_http_on_trailer_headers(nghttp2_stream *stream,
485|                                    nghttp2_frame *frame) {
486|  (void)stream;
487|
488|  if ((frame->hd.flags & NGHTTP2_FLAG_END_STREAM) == 0) {
489|    return -1;
490|  }
491|
492|  return 0;
493|}
494|
495|int nghttp2_http_on_remote_end_stream(nghttp2_stream *stream) {
496|  if (stream->http_flags & NGHTTP2_HTTP_FLAG_EXPECT_FINAL_RESPONSE) {
497|    return -1;
498|  }
499|
500|  if (stream->content_length != -1 &&
501|      stream->content_length != stream->recv_content_length) {
502|    return -1;
503|  }
504|
505|  return 0;
506|}
507|
508|int nghttp2_http_on_data_chunk(nghttp2_stream *stream, size_t n) {
509|  stream->recv_content_length += (int64_t)n;
510|
511|  if ((stream->http_flags & NGHTTP2_HTTP_FLAG_EXPECT_FINAL_RESPONSE) ||
512|      (stream->content_length != -1 &&
513|       stream->recv_content_length > stream->content_length)) {
514|    return -1;
515|  }
516|
517|  return 0;
518|}
