520|void nghttp2_http_record_request_method(nghttp2_stream *stream,
521|                                        nghttp2_frame *frame) {
522|  const nghttp2_nv *nva;
523|  size_t nvlen;
524|  size_t i;
525|
526|  switch (frame->hd.type) {
527|  case NGHTTP2_HEADERS:
528|    nva = frame->headers.nva;
529|    nvlen = frame->headers.nvlen;
530|    break;
531|  case NGHTTP2_PUSH_PROMISE:
532|    nva = frame->push_promise.nva;
533|    nvlen = frame->push_promise.nvlen;
534|    break;
535|  default:
536|    return;
537|  }
538|
539|  /* TODO we should do this strictly. */
540|  for (i = 0; i < nvlen; ++i) {
541|    const nghttp2_nv *nv = &nva[i];
542|    if (!(nv->namelen == 7 && nv->name[6] == 'd' &&
543|          memcmp(":metho", nv->name, nv->namelen - 1) == 0)) {
544|      continue;
545|    }
546|    if (lstreq("CONNECT", nv->value, nv->valuelen)) {
547|      stream->http_flags |= NGHTTP2_HTTP_FLAG_METH_CONNECT;
548|      return;
549|    }
550|    if (lstreq("HEAD", nv->value, nv->valuelen)) {
551|      stream->http_flags |= NGHTTP2_HTTP_FLAG_METH_HEAD;
552|      return;
553|    }
554|    return;
555|  }
556|}
