39|static int memieq(const void *a, const void *b, size_t n) {
40|  size_t i;
41|  const uint8_t *aa = a, *bb = b;
42|
43|  for (i = 0; i < n; ++i) {
44|    if (downcase(aa[i]) != downcase(bb[i])) {
45|      return 0;
46|    }
47|  }
48|  return 1;
