53|static int64_t parse_uint(const uint8_t *s, size_t len) {
54|  int64_t n = 0;
55|  size_t i;
56|  if (len == 0) {
57|    return -1;
58|  }
59|  for (i = 0; i < len; ++i) {
60|    if ('0' <= s[i] && s[i] <= '9') {
61|      if (n > INT64_MAX / 10) {
62|        return -1;
63|      }
64|      n *= 10;
65|      if (n > INT64_MAX - (s[i] - '0')) {
66|        return -1;
67|      }
68|      n += s[i] - '0';
69|      continue;
70|    }
71|    return -1;
72|  }
73|  return n;
74|}
