326|static int check_scheme(const uint8_t *value, size_t len) {
327|  const uint8_t *last;
328|  if (len == 0) {
329|    return 0;
330|  }
331|
332|  if (!(('A' <= *value && *value <= 'Z') || ('a' <= *value && *value <= 'z'))) {
333|    return 0;
334|  }
335|
336|  last = value + len;
337|  ++value;
338|
339|  for (; value != last; ++value) {
340|    if (!(('A' <= *value && *value <= 'Z') ||
341|          ('a' <= *value && *value <= 'z') ||
342|          ('0' <= *value && *value <= '9') || *value == '+' || *value == '-' ||
343|          *value == '.')) {
344|      return 0;
345|    }
346|  }
347|  return 1;
